#!/usr/bin/env python3
# -*- coding: ascii -*-
"""
Patch BlokQR M2c : pre-chauffage du navigateur (cale sur la version DEPLOYEE).

- Reecrit app/analyzers/dynamic_sandbox.py : pool de navigateur chaud + contexte
  neuf par requete + recyclage (usages/age/crash) + concurrence bornee + hooks
  prewarm/shutdown. AUCUN changement de comportement d'analyse : strictement la
  meme logique que ta prod, seul le cycle de vie du navigateur change.
  Securise : ecrit UNIQUEMENT si le fichier actuel correspond a ta version
  attendue (sinon ABORT, revue manuelle).
- Ajoute les reglages de pool dans app/config.py (apres always_dual_profile).
- Branche prewarm au demarrage + arret propre dans le lifespan de app/main.py.

Idempotent (2e execution = tout en SKIP), AST validee, application atomique
(aucune ecriture si une seule ancre manque). Lancer depuis /opt/blokqr/backend.
Apres application : rebuild de l'image.
"""
import ast, base64, os, sys
def d(s): return base64.b64decode(s).decode("utf-8")

WHOLE=[("app/analyzers/dynamic_sandbox.py", "", "")]
EDITS=[
    ("app/config.py", "ICAgIGFsd2F5c19kdWFsX3Byb2ZpbGU6IGJvb2wgPSBGaWVsZChkZWZhdWx0PUZhbHNlKQ==", ""),
    ("app/main.py", "ZnJvbSBhcHAuYXBpLnJvdXRlcyBpbXBvcnQgcm91dGVyCmZyb20gYXBwLmNvbmZpZyBpbXBvcnQgZ2V0X3NldHRpbmdzCmZyb20gYXBwLnNlY3VyaXR5LnNpZ25pbmcgaW1wb3J0IFZlcmRpY3RTaWduZXI=", "ZnJvbSBhcHAuYXBpLnJvdXRlcyBpbXBvcnQgcm91dGVyCmZyb20gYXBwLmNvbmZpZyBpbXBvcnQgZ2V0X3NldHRpbmdzCmZyb20gYXBwLmFuYWx5emVycy5keW5hbWljX3NhbmRib3ggaW1wb3J0IHByZXdhcm1fc2FuZGJveCwgc2h1dGRvd25fc2FuZGJveApmcm9tIGFwcC5zZWN1cml0eS5zaWduaW5nIGltcG9ydCBWZXJkaWN0U2lnbmVy"),
    ("app/main.py", "ICAgIGFwcC5zdGF0ZS5tYW5pZmVzdF9zaWduZXIgPSBNYW5pZmVzdFNpZ25lcihzZXR0aW5ncy5zcGhpbmNzX3Jvb3Rfa2V5X3BhdGgpCiAgICBhcHAuc3RhdGUuZ2F0ZXdheV9rZXlzID0gR2F0ZXdheUtleXMuZ2VuZXJhdGUoKSBpZiBzZXR0aW5ncy5lbmFibGVfcHFfZW52ZWxvcGUgZWxzZSBOb25lCiAgICB5aWVsZA==", ""),
]

def main():
    cache={}
    def load(f):
        if f not in cache:
            cache[f]=open(f,encoding="utf-8").read() if os.path.exists(f) else None
        return cache[f]
    changed=set()
    # --- Fichier complet (verification d'origine) ---
    for f,ob,tb in WHOLE:
        cur=load(f); origin=d(ob); target=d(tb)
        if cur is None: print("[ABORT] %s introuvable"%f); sys.exit(1)
        if cur==target: print("[SKIP] %s (deja a jour)"%f); continue
        if cur==origin: cache[f]=target; changed.add(f); print("[OK]   %s"%f)
        else:
            print("[ABORT] %s differe de la version attendue : revue manuelle "
                  "requise (aucune ecriture)."%f); sys.exit(1)
    # --- Editions ancrees ---
    pend=[]
    for i,(f,ob,nb) in enumerate(EDITS,1):
        src=load(f); old,new=d(ob),d(nb)
        if src is None: print("[ABORT] %s introuvable"%f); sys.exit(1)
        if new in src: pend.append(("skip",f,i)); continue
        if old not in src: print("[ABORT] edition %d : ancre absente dans %s"%(i,f)); sys.exit(1)
        cache[f]=src.replace(old,new,1); changed.add(f); pend.append(("ok",f,i))
    # --- AST de tout fichier modifie, PUIS ecriture (atomique) ---
    for f in sorted(changed):
        try: ast.parse(cache[f])
        except SyntaxError as e: print("[ABORT] AST invalide (%s): %s"%(f,e)); sys.exit(1)
    for f in sorted(changed): open(f,"w",encoding="utf-8").write(cache[f])
    for k,f,i in pend: print(("[OK]   " if k=="ok" else "[SKIP] ")+"%s#%d"%(f,i))
    print("\n%s"%("[OK] Patch M2c applique. Reconstruire l'image puis up -d." if changed else "Rien a faire (deja applique)."))

if __name__=="__main__": main()
